CREATE TABLE support_tickets (id UNIQUEIDENTIFIER NOT NULL PRIMARY KEY DEFAULT NEWID(), customer_id UNIQUEIDENTIFIER NOT NULL, facility_id UNIQUEIDENTIFIER NOT NULL, contract_id UNIQUEIDENTIFIER NULL, storage_unit_id UNIQUEIDENTIFIER NULL, subject NVARCHAR(255) NOT NULL, description NVARCHAR(2000) NOT NULL, status NVARCHAR(30) NOT NULL, priority NVARCHAR(20) NOT NULL, assigned_staff_id UNIQUEIDENTIFIER NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), created_by NVARCHAR(100) NULL, updated_by NVARCHAR(100) NULL, version BIGINT NOT NULL DEFAULT 0);
